<template>
    <div class="index">
        <h1>关系图谱</h1>
        <div class="list">
            <ul>
                <router-link tag="li" v-for="item in relation" :to="'/relation/'+item.id">
                    <div class="tools">
                        <i class="edit el-icon-s-tools" @click.stop="edit(item)"></i>
                        <i class="edit el-icon-delete-solid" @click.stop="del(item)"></i>
                    </div>
                    <div class="pic">
                        <i><img :src="item.pic"> </i>
                    </div>
                    <div class="title">
                        {{item.title}}
                    </div>
                </router-link>
                <li class="add" @click="add"><i class="el-icon-plus"></i></li>
            </ul>
        </div>
        <el-dialog
                :title="whichTitle"
                :visible.sync="showEditDialog"
                :close-on-click-modal="false"
        >
            <el-form :model="editForm" status-icon :rules="rules" ref="editForm" label-width="80px">
                <el-form-item label="图谱名称" prop="title">
                    <el-input v-model="editForm.title"></el-input>
                </el-form-item>
                <el-form-item label="封面图片" prop="pic">
                    <el-upload
                            class="avatar-uploader" :class="{tx:editForm.pic}"
                            action="https://jsonplaceholder.typicode.com/posts/"
                            :show-file-list="false"
                            :on-success="handleAvatarSuccess"
                            :before-upload="beforeAvatarUpload">
                        <template v-if="editForm.pic">
                            <img :src="editForm.pic" class="avatar">
                            <i class="el-icon-delete" @click.stop="handleRemove"></i>
                        </template>
                        <i v-else class="el-icon-plus avatar-uploader-icon"></i>
                    </el-upload>
                </el-form-item>
                <el-form-item>
                    <el-button type="primary" @click="submitForm('editForm')">提交</el-button>
                </el-form-item>
            </el-form>
        </el-dialog>
    </div>
</template>

<script>
    export default {
        name: 'index',
        data() {
            let validateTitle = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请输入关系图谱名称'));
                } else {
                    callback();
                }
            };
            let validatePic = (rule, value, callback) => {
                if (value === '') {
                    callback(new Error('请上传图片'));
                } else {
                    callback();
                }
            };
            return {
                relation: null,
                showEditDialog: false,
                currentRelation: null,
                editMode: 'add', // 'add' 或 'edit'
                editForm: {
                    title: '',
                    pic: '',
                    id: ''
                },
                rules: {
                    title: [
                        {required: true, validator: validateTitle, trigger: 'blur'}
                    ],
                    // pic: [
                    //     {required: true, validator: validatePic, trigger: 'blur'}
                    // ],
                },
            }
        },
        mounted() {
            if (this.$store.state.relation.relation === null) {
                this.$store.dispatch('relation/getAll').then((rs) => {
                    this.relation = rs
                })
            } else {
                this.relation = this.$store.state.relation.relation
            }
        },
        watch: {},
        computed: {
            whichTitle() {
                if (this.editMode === 'edit') {
                    return '修改关系图谱'
                } else {
                    return '新建一个关系图谱'
                }
            }
        },
        methods: {
            add() {
                this.editForm.title = ''
                this.editForm.pic = ''
                this.editForm.id = ''
                this.editMode = 'add'
                this.showEditDialog = true
            },
            edit(item) {
                this.editMode = 'edit'
                this.editForm.title = item.title
                this.editForm.pic = item.pic
                this.editForm.id = item.id
                this.showEditDialog = true
                this.currentRelation = item
            },
            submitForm(formName) {
                this.$refs[formName].validate((valid) => {
                    if (valid) {
                        this.saveEdit()
                    } else {
                        return false;
                    }
                });
            },
            async saveEdit() {
                if (this.editMode === 'add') {
                    let id = this.getId()
                    this.relation.unshift({title: this.editForm.title, pic: this.editForm.pic, id})
                    await this.$supabase.from('relation').insert({
                        id,
                        title: this.editForm.title,
                        pic: this.editForm.pic,
                    })
                    this.$message({
                        message: '添加成功',
                        type: 'success'
                    });

                } else if (this.editMode === 'edit') {
                    this.currentRelation.title = this.editForm.title
                    this.currentRelation.pic = this.editForm.pic
                    await this.$supabase.from('relation').update({
                        title: this.editForm.title,
                        pic: this.editForm.pic
                    }).eq('id', this.editForm.id)
                    this.$message({
                        message: '修改除成功',
                        type: 'success'
                    });
                }
                this.showEditDialog = false
                await this.$store.dispatch('relation/getAll')
            },
            async del(data) {
                let index = this.relation.indexOf(data)
                this.relation.splice(index, 1)
                await this.$supabase
                    .from('relation')
                    .delete()
                    .eq('id', data.id)
                this.$message({
                    message: '删除成功',
                    type: 'success'
                });
                await this.$store.dispatch('relation/getAll')
            },
            getId() {
                let id
                if (this.relation.length > 0) {
                    let maxObject = this.relation.reduce((prev, current) => (prev.id > current.id ? prev : current));
                    id = maxObject.id + 1
                } else {
                    id = 1
                }
                return id
            },
            async handleRemove() {
                this.editForm.pic = ''
                let arr = this.currentRelation.pic.split('/')
                let len = arr.length
                const {data} = await this.$supabase
                    .storage
                    .from('my')
                    .remove(arr[len - 1])
                this.$message.success('图片删除成功！');
            },
            async handleAvatarSuccess(res, file) {
                //this.editForm.photo = URL.createObjectURL(file.raw);
                const {error} = await this.$supabase
                    .storage
                    .from('my')
                    .upload(file.name, file.raw)
                if (error) {
                    this.$message.error(error);
                } else {
                    this.$message.success('图片上传成功！');
                    const {data} = await this.$supabase
                        .storage
                        .from('my')
                        .getPublicUrl(file.name)
                    this.editForm.pic = data.publicUrl
                }

            },
            beforeAvatarUpload(file) {
                let types = ['image/jpeg', 'image/png', 'image/gif']
                const isJPG = types.indexOf(file.type) > -1;
                const isLt2M = file.size / 1024 / 1024 < 2;

                if (!isJPG) {
                    this.$message.error('上传头像只能是jpg,png,gif图片格式!');
                }
                if (!isLt2M) {
                    this.$message.error('上传头像图片大小不能超过2MB!');
                }
                return isJPG && isLt2M;
            },


        }
    }
</script>
<style scoped>
    .index {
        width: 100%;
        /*max-width: 1000px;*/
        margin: 0 auto;
        padding: 15px;
        display: flex;
        flex-direction: column;
        gap: 2vw
    }

    .index h1 {
        font-size: clamp(30px, 3vw, 50px);
        font-weight: 700;
        padding-top: 3vw;
    }


    .index .list ul {
        display: flex;
        align-items: stretch;
        flex-wrap: wrap;
        gap: 1vw;
        width: calc(100% + 1vw);
    }

    .index .list ul li {
        background: var(--white);
        width: calc(16.666666666667% - 1vw);
        border-radius: 2px;
        position: relative;
        cursor: pointer;
    }
    .index .list ul li .pic{
        display: flex;
    }
    .index .list ul li .pic i{
        width: 100%;
        padding-bottom: 46%;
        position: relative;
    }
    .index .list ul li .pic i img{
        width: 100%;
        height: 100%;object-fit: cover;
        position: absolute;
    }
    .index .list ul li .title{
        padding: 10px 10px;
    }




    .index .list ul li .tools {
        position: absolute;
        right: .5em;
        top: .5em;
        display: flex;
        align-items: center;
        flex-direction: row;gap:5px;
        z-index: 1;
    }

    .index .list ul li .tools i {
        font-size: calc(clamp(30px, 3vw, 50px) * 0.3);
        color: var(--white);
    }



    .index .list ul li.add {
        display: flex;
        align-items: center;
        justify-content: center;
    }

    .index .list ul li.add i {
        font-size: 3vw;
        color: #5F92BDFF;
    }


    @media (max-width: 768px) {
        .index .list ul {
            gap: 3vw;
            width: calc(100% + 3vw);

        }

        .index .list ul li {
            width: calc(50% - 3vw);
        }

        .index .list ul li.add i {
            font-size: 6vw;
        }

    }
</style>

